}

export function CardFooter({
  className,
  ...props
}: ComponentPropsWithRef<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn(
        "flex flex-wrap items-center gap-3 px-6 pb-6 first:pt-6 [[data-slot=card-header]+&]:pt-5",
        className,
