export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  createContext,
  type HTMLAttributes,
  type ReactNode,
  useContext,
} from "react";
import {
  Radio as AriaRadio,
  RadioGroup as AriaRadioGroup,
  type RadioGroupProps as AriaRadioGroupProps,
  type RadioProps as AriaRadioProps,
  composeRenderProps,
  FieldError,
  Label,
  Text,
} from "react-aria-components";
import { tv, type VariantProps } from "tailwind-variants";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import { fieldDescriptionStyles, fieldErrorStyles } from "./field-styles";

const radioStyles = tv({
  base: "group flex min-h-11 cursor-pointer items-center gap-3 rounded-md text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring read-only:cursor-default disabled:cursor-default disabled:opacity-50",
  variants: {
    variant: {
      default: "",
      card: "min-h-14 rounded-lg bg-card px-4 py-3 shadow-[var(--shadow-card)] ring-1 ring-border transition-[background-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted selected:bg-accent selected:ring-primary/40",
    },
  },
  defaultVariants: { variant: "default" },
});

const RadioStateContext = createContext({
  isSelected: false,
  isHovered: false,
  isPressed: false,
});

export interface RadioGroupProps
  extends Omit<AriaRadioGroupProps, "children" | "className"> {
  label?: string;
  description?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaRadioGroupProps["className"];
  children: ReactNode;
  onValueChange?: (value: string) => void;
}

export function RadioGroup({
  label,
  description,
  className,
  children,
  onValueChange,
  ...props
}: RadioGroupProps) {
  return (
    <AriaRadioGroup
      {...props}
      data-slot="radio-group"
      onChange={(value) => {
        props.onChange?.(value);
        onValueChange?.(value);
      }}
      className={composeRenderProps(className, (className) =>
        cn("group/radio-group grid gap-1", className),
      )}
    >
      {label && <RadioGroupLabel>{label}</RadioGroupLabel>}
      {description && (
        <RadioGroupDescription>{description}</RadioGroupDescription>
      )}
      {label ? (
        <>
          <RadioGroupItems>{children}</RadioGroupItems>
          <RadioGroupError />
        </>
      ) : (
        children
      )}
    </AriaRadioGroup>
  );
}

export interface RadioProps
  extends Omit<AriaRadioProps, "children" | "className"> {
  label?: string;
  description?: string;
  variant?: NonNullable<VariantProps<typeof radioStyles>["variant"]>;
  ref?: React.Ref<HTMLLabelElement>;
  className?: AriaRadioProps["className"];
  children?: AriaRadioProps["children"];
}

export function Radio({
  label,
  description,
  variant = "default",
  className,
  children,
  ...props
}: RadioProps) {
  return (
    <AriaRadio
      {...props}
      data-slot="radio"
      data-variant={variant}
      className={composeRenderProps(className, (className) =>
        radioStyles({
          variant,
          className: cn(description && "items-start", className),
        }),
      )}
    >
      {(state) => (
        <RadioStateContext.Provider value={state}>
          {typeof children === "function"
            ? children(state)
            : (children ?? (
                <>
                  <RadioIndicator />
                  <span className="min-w-0">
                    {label && <RadioLabel>{label}</RadioLabel>}
                    {description && (
                      <RadioDescription>{description}</RadioDescription>
                    )}
                  </span>
                </>
              ))}
        </RadioStateContext.Provider>
      )}
    </AriaRadio>
  );
}

export function RadioGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="radio-group-label"
      className={cn("text-sm font-semibold text-foreground", className)}
    />
  );
}

export function RadioGroupDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="radio-group-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

export function RadioGroupItems({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="radio-group-items"
      className={cn(
        "grid gap-1 pt-2 group-data-[orientation=horizontal]/radio-group:flex group-data-[orientation=horizontal]/radio-group:flex-wrap group-data-[orientation=horizontal]/radio-group:gap-x-6",
        className,
      )}
    />
  );
}

export function RadioGroupError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="radio-group-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}

export function RadioIndicator({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isHovered, isPressed } = useContext(RadioStateContext);
  const reduceMotion = useReducedMotion();
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="radio-indicator"
      className={cn(
        "grid size-5 shrink-0 place-items-center rounded-full border border-input bg-card shadow-[var(--shadow-inset)] transition-[border-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover:border-primary/60 group-invalid:border-destructive group-invalid:group-hover:border-destructive group-selected:border-primary",
        className,
      )}
    >
      <motion.span
        initial={false}
        animate={{
          scale: isSelected ? (isPressed ? 0.85 : isHovered ? 1.12 : 1) : 0.86,
          opacity: isSelected ? 1 : 0,
        }}
        transition={{
          duration: reduceMotion ? 0 : duration.fast,
          ease: easeOut,
        }}
        className="size-2 rounded-full bg-primary"
      />
    </span>
  );
}

export function RadioLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="radio-label"
      className={cn("block text-sm font-medium", className)}
    />
  );
}

export function RadioDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="radio-description"
      className={cn(
        "mt-1 block text-xs leading-5 text-muted-foreground",
        className,
      )}
    />
  );
}

export const RadioGroupItem = Radio;

"use client";

import { motion, useReducedMotion } from "motion/react";
import { createContext, useContext } from "react";
import {
  Switch as AriaSwitch,
  type SwitchProps as AriaSwitchProps,
  composeRenderProps,
  useLocale,
} from "react-aria-components";
import { springSnappy, transitionFor } from "./motion";
import { cn } from "./utils";

const SwitchStateContext = createContext({
  isSelected: false,
  isPressed: false,
  isDisabled: false,
});

export interface SwitchProps
  extends Omit<AriaSwitchProps, "className" | "children"> {
  ref?: React.Ref<HTMLLabelElement>;
  className?: AriaSwitchProps["className"];
  description?: string;
  children?: AriaSwitchProps["children"];
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

export function Switch({
  children,
  description,
  className,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: SwitchProps) {
  return (
    <AriaSwitch
      {...props}
      isSelected={checked ?? props.isSelected}
      defaultSelected={defaultChecked ?? props.defaultSelected}
      onChange={(value) => {
        props.onChange?.(value);
        onCheckedChange?.(value);
      }}
      data-slot="switch"
      className={composeRenderProps(className, (className) =>
        cn(
          "group inline-flex min-h-11 cursor-pointer items-center justify-between gap-4 text-sm text-foreground outline-none disabled:cursor-default disabled:opacity-50",
          className,
        ),
      )}
    >
      {(state) => (
        <SwitchStateContext.Provider value={state}>
          {typeof children === "function" ? (
            children(state)
          ) : typeof children === "string" || children == null ? (
            <>
              {(children || description) && (
                <span className="min-w-0">
                  {children && (
                    <span className="block font-medium">{children}</span>
                  )}
                  {description && (
                    <span className="mt-1 block text-xs leading-5 text-muted-foreground">
                      {description}
                    </span>
                  )}
                </span>
              )}
              <SwitchControl>
                <SwitchThumb />
              </SwitchControl>
            </>
          ) : (
            children
          )}
        </SwitchStateContext.Provider>
      )}
    </AriaSwitch>
  );
}

export function SwitchLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="switch-label"
      className={cn("block font-medium", className)}
    />
  );
}

export function SwitchDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="switch-description"
      className={cn(
        "mt-1 block text-xs leading-5 text-muted-foreground",
        className,
      )}
    />
  );
}

export function SwitchControl({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="switch-control"
      className={cn(
        "flex h-6 w-10 shrink-0 items-center rounded-full bg-foreground/60 p-0.5 group-hover:bg-foreground/70 group-selected:bg-primary group-selected:hover:bg-primary/90 group-focus-visible:outline-2 group-focus-visible:outline-solid group-focus-visible:outline-offset-2 group-focus-visible:outline-ring forced-colors:border forced-colors:border-[ButtonText] motion-safe:transition-colors motion-safe:duration-200",
        className,
      )}
    />
  );
}

export function SwitchThumb({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isPressed, isDisabled } = useContext(SwitchStateContext);
  const { direction } = useLocale();
  const reduceMotion = useReducedMotion();
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="switch-thumb"
      className={cn("contents", className)}
    >
      <motion.span
        initial={false}
        animate={{
          x: isSelected ? (direction === "rtl" ? -16 : 16) : 0,
          scaleX: !isDisabled && isPressed ? 1.1 : 1,
        }}
        transition={transitionFor(reduceMotion, springSnappy)}
        className="size-5 rounded-full bg-card group-selected:bg-primary-foreground forced-colors:bg-[ButtonText] motion-safe:transition-colors motion-safe:duration-200"
      />
    </span>
  );
}

"use client";

import { useState } from "react";
import { Button } from "../../../components/vip-ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "../../../components/vip-ui/card";
import { Checkbox } from "../../../components/vip-ui/checkbox";
import { Radio, RadioGroup } from "../../../components/vip-ui/radio-group";
import { Switch } from "../../../components/vip-ui/switch";

const channels = ["Email", "Push", "Slack"] as const;
type Channel = (typeof channels)[number];

const events = [
  { id: "mentions", label: "Mentions", description: "Someone tags you." },
  { id: "comments", label: "Comments", description: "On items you follow." },
  { id: "assigned", label: "Assignments", description: "A task is yours." },
  { id: "deploys", label: "Failed deploys", description: "A build stops." },
  { id: "summary", label: "Weekly summary", description: "Each Monday." },
] as const;
type EventId = (typeof events)[number]["id"];

const initialMatrix: Record<EventId, Channel[]> = {
  mentions: ["Email", "Push", "Slack"],
  comments: ["Push"],
  assigned: ["Email", "Slack"],
  deploys: ["Email", "Push", "Slack"],
  summary: ["Email"],
};

export function NotificationSettings() {
  const [matrix, setMatrix] = useState(initialMatrix);
  const [paused, setPaused] = useState(false);
  const [saved, setSaved] = useState(false);

  function toggle(event: EventId, channel: Channel, on: boolean) {
    setSaved(false);
    setMatrix((current) => ({
      ...current,
      [event]: on
        ? [...current[event], channel]
        : current[event].filter((item) => item !== channel),
    }));
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle as="h1" className="text-xl">
          Notifications
        </CardTitle>
        <CardDescription>
          Choose where we tell you about each event.
        </CardDescription>
      </CardHeader>
      <CardContent className="grid gap-6">
        <Switch
          checked={paused}
          onCheckedChange={(value) => {
            setSaved(false);
            setPaused(value);
          }}
          description="We keep all events and send nothing until you turn this off."
          className="w-full rounded-lg bg-muted/60 px-4 py-3 ring-1 ring-border/70"
        >
          Pause all notifications
        </Switch>
        <div className="-mx-6 overflow-x-auto px-6">
          <table className="w-full min-w-[420px] border-separate border-spacing-0 text-sm">
            <caption className="sr-only">
              Notification channels for each event
            </caption>
            <thead>
              <tr>
                <th
                  scope="col"
                  className="border-b border-border pb-3 text-start text-xs font-semibold text-muted-foreground"
                >
                  Event
                </th>
                {channels.map((channel) => (
                  <th
                    key={channel}
                    scope="col"
                    className="w-20 border-b border-border pb-3 text-center text-xs font-semibold text-muted-foreground"
                  >
                    {channel}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {events.map((event) => (
                <tr key={event.id}>
                  <th
                    scope="row"
                    className="border-b border-border/70 py-3 pe-4 text-start font-normal"
                  >
                    <span className="block font-medium">{event.label}</span>
                    <span className="block text-xs text-muted-foreground">
                      {event.description}
                    </span>
                  </th>
                  {channels.map((channel) => (
                    <td
                      key={channel}
                      className="border-b border-border/70 text-center"
                    >
                      <Checkbox
                        aria-label={`${event.label} by ${channel}`}
                        isDisabled={paused}
                        checked={matrix[event.id].includes(channel)}
                        onCheckedChange={(on) => toggle(event.id, channel, on)}
                        className="justify-center"
                      />
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <RadioGroup
          label="Email delivery"
          defaultValue="hourly"
          isDisabled={paused}
          onChange={() => setSaved(false)}
        >
          <Radio value="instant" label="Right away" />
          <Radio
            value="hourly"
            label="Once an hour"
            description="One email with all events from the last hour."
          />
          <Radio
            value="daily"
            label="Once a day"
            description="One email at 9:00 in your time zone."
          />
        </RadioGroup>
      </CardContent>
      <CardFooter className="justify-end border-t border-border/70 pt-5">
        <output className="me-auto text-sm text-muted-foreground">
          {saved ? "Settings saved." : ""}
        </output>
        <Button
          variant="ghost"
          onPress={() => {
            setMatrix(initialMatrix);
            setPaused(false);
            setSaved(false);
          }}
        >
          Reset
        </Button>
        <Button onPress={() => setSaved(true)}>Save</Button>
      </CardFooter>
    </Card>
  );
}

import type { Metadata } from "next";
import { NotificationSettings } from "./notification-settings";

export const metadata: Metadata = {
  title: "Notification settings",
};

export default function NotificationsPage() {
  return (
    <main className="flex min-h-svh items-start justify-center bg-muted/40 p-6 md:p-10">
      <div className="w-full max-w-2xl">
        <NotificationSettings />
      </div>
    </main>
  );
}
